    if x0 < 24 or x1 > 1056:
        problems.append(f"canvas overflow: '{t['content'][:18]}' est [{x0:.0f},{x1:.0f}]")
    # smallest enclosing rect containing anchor point
    best = None
    for r in rects:
        rx, ry, rw, rh = rect_box(r)
        if rw >= 1070: continue  # background
        if rx <= x <= rx+rw and ry-2 <= y <= ry+rh+2:
            if best is None or rw*rh < best[2]*best[3]:
                best = (rx, ry, rw, rh)
    if best:
        rx, ry, rw, rh = best
        if x0 < rx + 6 or x1 > rx + rw - 6:
            problems.append(f"truncation risk: '{t['content'][:20]}' est [{x0:.0f},{x1:.0f}] in rect x=[{rx:.0f},{rx+rw:.0f}]")

# ---- 3. paper masks drawn BEFORE a node must not overlap that later node body ----
def overlaps(b1, b2):
    return not (b1[0]+b1[2] <= b2[0] or b2[0]+b2[2] <= b1[0] or
                b1[1]+b1[3] <= b2[1] or b2[1]+b2[3] <= b1[1])
node_bodies = [e for e in rects if e["a"].get("stroke") and float(e["a"]["width"]) >= 160]
label_masks = [e for e in rects if e["a"].get("fill") in ("#f5f5f5","#ffffff") and float(e["a"]["width"]) < 200]
for mrect in label_masks:
    for nb in node_bodies:
        if nb["pos"] > mrect["pos"] and overlaps(rect_box(mrect), rect_box(nb)):
            problems.append(f"mask-under-node: mask@{rect_box(mrect)} vs node@{rect_box(nb)}")

